def transform(grid):
    # General rule demonstrated: recolor the small object immediately before
    # the long straight marker, using that marker's color.
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    cells = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                cells.setdefault(v, []).append((r, c))

    # Find a long straight run (the marker) and recolor the closest compact
    # object located before it along the run's direction.
    best = None
    for color, pts in cells.items():
        s = set(pts)
        for r, c in pts:
            for dr, dc in ((1, 0), (0, 1)):
                length = 1
                while (r + dr * length, c + dc * length) in s:
                    length += 1
                if length >= 5 and (best is None or length > best[0]):
                    best = (length, color, r, c, dr, dc)
    if best is None:
        return [row[:] for row in grid]

    length, marker, r, c, dr, dc = best
    # Extend the marker's line backwards, locating the nearest other-color
    # non-background component adjacent to that line.
    candidates = []
    for color, pts in cells.items():
        if color == marker:
            continue
        distance = min(abs((y-r)*dc - (x-c)*dr) +
                       abs((y-r)*dr + (x-c)*dc)
                       for y, x in pts)
        candidates.append((distance, color, pts))
    if not candidates:
        return [row[:] for row in grid]
    _, _, target = min(candidates, key=lambda z: z[0])
    out = [row[:] for row in grid]
    for y, x in target:
        out[y][x] = marker
    return out
